// Port of src/llm_sim_bench/report.py: estimate reports as JSON and Markdown.
// Python is the reference; web/test/report.json (generated by `llmsimbench export-web`)
// keeps the two in sync. Reports are in English; notes and warnings carry a code and
// parameters, which the app also uses to show them in the interface language.

import { buildSystem, estimate } from "./estimator.js";
import { benchGenTps, groupCpuRuns } from "./measured.js";

export const SCHEMA = "llmsimbench.report/1";
export const BACKEND_NAMES = { cuda: "CUDA", metal: "Metal", rocm: "ROCm", vulkan: "Vulkan", sycl: "SYCL", cpu: "CPU" };

const TEXTS = {
  context_exceeds_max: "Context {context} exceeds the model's maximum of {max}.",
  ram_short: "Needs {need_gb} GB in system RAM but only {free_gb} GB is free; it would page to disk.",
  layers_on_cpu: "{cpu_layers} of {total_layers} layers are offloaded to the CPU.",
  prefill_device_uncalibrated: "No prompt-processing measurements for {device} with this backend: its prompt speed uses the backend average and can be far off.",
  cpu_device_uncalibrated: "No decode measurements for the {cpu}: its memory efficiency uses the CPU average. Single-CCD Ryzen parts measure about 25 % slower than that.",
  backend_uncalibrated: "No measured {backend} results yet, so its speeds are uncalibrated guesses.",
  decode_uncalibrated: "{backend} generation speed is not calibrated yet.",
  prefill_uncalibrated: "{backend} prompt processing speed is not calibrated yet.",
  moe_routing: "Mixture-of-experts routing overhead is not modeled, so generation may be optimistic.",
};

function item(code, params = {}) {
  const shown = (v) => (Number.isInteger(v) ? fmt(v, 0) : String(v));
  return { code, params, text: TEXTS[code].replace(/\{(\w+)\}/g, (_, k) => shown(params[k])) };
}

// Python's f"{x:,.{digits}f}": grouping commas and round-half-even on the exact value.
const formatters = new Map();
export function fmt(x, digits) {
  if (!formatters.has(digits)) {
    formatters.set(digits, new Intl.NumberFormat("en-US", {
      minimumFractionDigits: digits, maximumFractionDigits: digits, roundingMode: "halfEven",
    }));
  }
  return formatters.get(digits).format(x);
}

function label(P, name) {
  for (const list of [P.gpus, P.unified, P.cpus]) {
    const hit = list.find((x) => x.name === name);
    if (hit && hit.label) return hit.label;
  }
  return name;
}

function deviceLabel(P, system, p) {
  if (p.is_gpu) return label(P, p.device);
  return system.unified ? "CPU" : `CPU ${label(P, system.cpu.name)}`;
}

function systemInfo(P, system) {
  return {
    kind: system.unified ? "unified" : "pc",
    cpu: system.unified ? null : { name: system.cpu.name, label: label(P, system.cpu.name) },
    ram_gb: system.ram.size_gb,
    ram_bandwidth_gbps: system.ram.bandwidth_gbps,
    gpus: system.gpus.map((g) => ({
      name: g.name, label: label(P, g.name), backend: g.backend,
      vram_gb: system.unified ? null : g.vram_gb,
    })),
  };
}

export function notes(system, est) {
  const out = [];
  const m = est.model;
  const cpu = est.placements.find((p) => !p.is_gpu);
  if (est.context > m.max_context) out.push(item("context_exceeds_max", { context: est.context, max: m.max_context }));
  if (cpu && !est.fits) out.push(item("ram_short", { need_gb: fmt(est.ram_needed_gb, 1), free_gb: fmt(est.ram_free_gb, 1) }));
  if (cpu && system.gpus.length) out.push(item("layers_on_cpu", { cpu_layers: cpu.layers, total_layers: m.n_layers }));
  return out;
}

// Where the numbers rest on uncalibrated assumptions rather than measurements.
export function warnings(P, system, est) {
  const cal = P.calibration;
  const eff = P.efficiency;
  const backends = [...new Set(est.placements.map((p) => (p.is_gpu
    ? system.gpus.find((g) => g.name === p.device).backend : "cpu")))];
  const out = [];
  const devices = [];
  for (const g of system.gpus) {
    if (`${g.backend}/pp` in cal && !(`${g.name}|${g.backend}` in eff.device_compute)) {
      if (!devices.includes(label(P, g.name))) devices.push(label(P, g.name));
    }
  }
  for (const device of devices) out.push(item("prefill_device_uncalibrated", { device }));
  if (backends.includes("cpu") && !system.unified && !(`${system.cpu.name}|cpu` in eff.device_bandwidth)) {
    out.push(item("cpu_device_uncalibrated", { cpu: label(P, system.cpu.name) }));
  }
  for (const b of backends) {
    const tg = `${b}/tg` in cal;
    const pp = `${b}/pp` in cal;
    if (!tg && !pp) out.push(item("backend_uncalibrated", { backend: BACKEND_NAMES[b] }));
    else if (!tg) out.push(item("decode_uncalibrated", { backend: BACKEND_NAMES[b] }));
    else if (!pp) out.push(item("prefill_uncalibrated", { backend: BACKEND_NAMES[b] }));
  }
  if (est.model.active_params_b) out.push(item("moe_routing"));
  return out;
}

// Seconds for tokens 2..maxTokens of a reply after `filled` context tokens.
export function genTime(est, filled, maxTokens) {
  let t = 0;
  for (let i = 1; i < maxTokens; i++) t += 1 / est.decodeTpsAt(filled + i);
  return t;
}

const withBackend = (system, backend) => ({ ...system, gpus: system.gpus.map((g) => ({ ...g, backend })) });
const model = (P, name) => P.models.find((m) => m.name === name);

// Benchmarks of the selected GPU (single-GPU PC) or chip, each simulated with the
// backend, model and test size of the run.
export function gpuChecks(P, system, kvBits) {
  if (system.gpus.length !== 1) return null;
  const rows = P.measurements.filter((m) => m.preset === system.gpus[0].name);
  if (!rows.length) return null;
  return {
    kind: "gpu",
    rows: rows.map((m) => {
      const est = estimate(withBackend(system, m.backend.toLowerCase()), model(P, m.model), m.quant,
                           m.n_prompt + m.n_gen, kvBits, P.efficiency, P.quant_bpw);
      return {
        backend: m.backend, model: m.model, quant: m.quant, flash_attn: m.flash_attn,
        old_build: m.old_build, n_prompt: m.n_prompt, n_gen: m.n_gen,
        tg_measured: m.tg_tps, tg_simulated: m.n_gen / genTime(est, 0, m.n_gen + 1),
        pp_measured: m.pp_tps, pp_simulated: est.prefill_tps, sources: [1],
      };
    }),
    sources: [rows[0].source],
  };
}

// CPU-only runs on the selected CPU, each simulated with the memory that run used.
export function cpuChecks(P, system) {
  if (system.gpus.length || system.unified) return null;
  const { groups, sources } = groupCpuRuns(P.cpu_measurements.filter((m) => m.preset === system.cpu.name));
  if (!groups.length) return null;
  return {
    kind: "cpu",
    rows: groups.map((g) => {
      const sim = { cpu: system.cpu, ram: { size_gb: 1024, bandwidth_gbps: g.ram_bandwidth_gbps || 1 }, gpus: [], unified: false };
      const est = estimate(sim, model(P, g.sim_model), g.quant, Math.max(g.n_prompt || 0, g.n_gen || 0, 1),
                           16, P.efficiency, P.quant_bpw);
      return {
        backend: "CPU", model: g.model, quant: g.quant, dimms: g.dimms, mem_mts: g.mem_mts,
        threads: g.threads, n_prompt: g.n_prompt, n_gen: g.n_gen, runs: g.n,
        tg_measured: g.tg_tps, tg_simulated: g.tg_tps != null ? benchGenTps(est, g.n_gen) : null,
        pp_measured: g.pp_tps, pp_simulated: g.pp_tps != null ? est.prefill_tps : null,
        sources: g.sources,
      };
    }),
    sources,
  };
}

// Time to the first token and to the whole reply for {prompt_tokens, max_tokens, depth},
// as the mock plays it.
export function timingInfo(est, timing) {
  const ttft = timing.prompt_tokens / est.prefill_tps;
  const gen = genTime(est, timing.depth + timing.prompt_tokens, timing.max_tokens);
  return { ...timing, ttft_s: ttft, reply_s: ttft + gen };
}

// One configuration's part of a report; `timing` adds timingInfo().
export function result(P, system, est, kvBits, timing = null, lbl = null) {
  const m = est.model;
  return {
    label: lbl,
    config: {
      system: systemInfo(P, system),
      model: { name: m.name, params_b: m.params_b, active_params_b: m.active_params_b ?? null,
               layers: m.n_layers, max_context: m.max_context },
      quant: est.quant, context: est.context, kv_bits: kvBits,
    },
    memory: {
      weights_gb: est.weights_gb, kv_gb: est.kv_gb, total_gb: est.weights_gb + est.kv_gb,
      fits: est.fits, ram_needed_gb: est.ram_needed_gb, ram_free_gb: est.ram_free_gb,
      placements: est.placements.map((p) => ({
        device: p.device, label: deviceLabel(P, system, p), is_gpu: p.is_gpu, layers: p.layers,
        weights_gb: p.weights_gb, kv_gb: p.kv_gb,
      })),
    },
    speed: { prefill_tps: est.prefill_tps, decode_tps_empty: est.decode_tps_empty, decode_tps_full: est.decode_tps_full },
    timing: timing ? timingInfo(est, timing) : null,
    notes: notes(system, est),
    warnings: warnings(P, system, est),
    check: gpuChecks(P, system, kvBits) || cpuChecks(P, system),
  };
}

// configs: [{label, system: spec as in buildSystem, model, quant, context, kv_bits, timing}]
export function buildReport(P, configs, surface = "web", shareUrl = null) {
  const results = configs.map((c) => {
    const system = buildSystem(c.system, P);
    const est = estimate(system, model(P, c.model), c.quant, c.context, c.kv_bits, P.efficiency, P.quant_bpw);
    return result(P, system, est, c.kv_bits, c.timing ?? null, c.label ?? null);
  });
  return {
    schema: SCHEMA,
    generated_by: { tool: "llmsimbench", version: P.version, surface },
    share_url: shareUrl,
    results,
  };
}

// ---------- Markdown ----------

export function fmtTps(x) {
  if (x == null) return "–";
  if (x >= 100) return fmt(x, 0);
  if (x >= 10) return fmt(x, 1);
  return fmt(x, 2);
}

export function fmtTime(s) {
  // Compare the rounded text, so 59.96 s reads "1 min 00 s" rather than "60.0 s".
  if (fmt(s * 1000, 0) !== "1,000" && s < 1) return `${fmt(s * 1000, 0)} ms`;
  if (fmt(s, 1) !== "60.0" && s < 60) return `${fmt(s, 1)} s`;
  const n = Number(fmt(s, 0).replace(/,/g, ""));
  const m = Math.floor(n / 60);
  const sec = n % 60;
  return m < 60 ? `${m} min ${String(sec).padStart(2, "0")} s`
    : `${Math.floor(m / 60)} h ${String(m % 60).padStart(2, "0")} min`;
}

const cell = (x) => String(x).replace(/\|/g, "\\|");

function table(head, rows, align = "") {
  const a = align || `l${"r".repeat(head.length - 1)}`;
  return [
    `| ${head.join(" | ")} |`,
    `|${[...a].map((c) => (c === "l" ? " --- " : " ---: ")).join("|")}|`,
    ...rows.map((r) => `| ${r.map(cell).join(" | ")} |`),
  ];
}

// Python's f"{x:g}" for the parameter counts in the presets.
const g6 = (x) => String(Number(x.toPrecision(6)));

function systemLine(s) {
  const gpus = s.gpus.map((g) => `${g.label} (${BACKEND_NAMES[g.backend]})`).join(", ");
  if (s.kind === "unified") {
    return `${gpus}, ${fmt(s.ram_gb, 0)} GB unified memory (${fmt(s.ram_bandwidth_gbps, 0)} GB/s)`;
  }
  return `CPU ${s.cpu.label} · RAM ${fmt(s.ram_gb, 0)} GB (${fmt(s.ram_bandwidth_gbps, 1)} GB/s) · GPU ${gpus || "none"}`;
}

function modelLine(c) {
  const m = c.model;
  const size = `${g6(m.params_b)}B${m.active_params_b ? `, ${g6(m.active_params_b)}B active` : ""}`;
  return `${m.name} (${size}), ${c.quant}, context ${fmt(c.context, 0)}, KV cache ${c.kv_bits}-bit`;
}

function checkLines(check) {
  const rows = check.rows.map((r) => {
    let run;
    if (check.kind === "gpu") {
      run = `${r.backend} · ${r.quant}${r.flash_attn ? " · FA" : ""}${r.old_build ? " (2023 build)" : ""}`;
    } else {
      const memory = r.dimms && r.mem_mts ? `${r.mem_mts} MT/s × ${r.dimms}` : "memory not stated";
      const test = [r.n_prompt ? `pp${r.n_prompt}` : "", r.n_gen ? `tg${r.n_gen}` : ""].filter(Boolean).join(" ");
      const meta = [memory, r.threads ? `${r.threads} threads` : "", test, `×${r.runs}`].filter(Boolean);
      run = `${r.model} · ${r.quant} · ${meta.join(" · ")}`;
    }
    const refs = r.sources.map((n) => `[${n}]`).join("");
    return [`${run} ${refs}`, fmtTps(r.tg_measured), fmtTps(r.tg_simulated), fmtTps(r.pp_measured), fmtTps(r.pp_simulated)];
  });
  const lines = ["### Check against real benchmarks", "",
    "llama.cpp results on this hardware, measured vs. this simulator (tok/s)."
    + (check.kind === "cpu" ? " CPU rows are simulated with the memory each run used." : ""), "",
    ...table(["Run", "Gen real", "Gen sim", "Prompt real", "Prompt sim"], rows)];
  if (check.rows.some((r) => r.old_build)) {
    lines.push("", "Rows marked as 2023 builds ran on an older, slower llama.cpp; current builds are faster.");
  }
  lines.push("", ...check.sources.map((url, i) => `[${i + 1}] ${url}  `));
  lines[lines.length - 1] = lines[lines.length - 1].trimEnd();
  return lines;
}

function resultLines(r, heading) {
  const { config: c, memory: mem, speed: sp } = r;
  const lines = [`## ${heading}`, "",
    ...table(["", ""], [["System", systemLine(c.system)], ["Model", modelLine(c)]], "ll"),
    "", "### Memory", ""];
  const rows = mem.placements.map((p) => [p.label, p.layers, fmt(p.weights_gb, 2), fmt(p.kv_gb, 2)]);
  rows.push(["Total", c.model.layers, fmt(mem.weights_gb, 2), fmt(mem.kv_gb, 2)]);
  lines.push(...table(["Device", "Layers", "Weights GB", "KV cache GB"], rows));
  lines.push("", `Fits in memory: ${mem.fits ? "yes" : "**no**"}`, "", "### Speed", "");
  const speed = [["Generation, empty context", `${fmtTps(sp.decode_tps_empty)} tok/s`],
    ["Generation, full context", `${fmtTps(sp.decode_tps_full)} tok/s`],
    ["Prompt processing", `${fmtTps(sp.prefill_tps)} tok/s`]];
  if (r.timing) {
    const t = r.timing;
    const depth = t.depth ? `, ${fmt(t.depth, 0)} tokens already cached` : "";
    speed.push([`First token (${fmt(t.prompt_tokens, 0)} prompt tokens${depth})`, fmtTime(t.ttft_s)],
               [`Whole reply (${fmt(t.max_tokens, 0)} tokens)`, fmtTime(t.reply_s)]);
  }
  lines.push(...table(["Metric", "Estimate"], speed));
  if (r.notes.length) lines.push("", "### Notes", "", ...r.notes.map((n) => `- ${n.text}`));
  if (r.warnings.length) lines.push("", "### Estimate only", "", ...r.warnings.map((w) => `- ${w.text}`));
  if (r.check) lines.push("", ...checkLines(r.check));
  return lines;
}

export function markdown(rep) {
  const g = rep.generated_by;
  const lines = ["# LLM Sim Bench report", "",
    `Generated by llmsimbench ${g.version} (${g.surface}). These are estimates from a first-order model, not measurements.`];
  if (rep.share_url) lines.push("", `Setup link: <${rep.share_url}>`);
  for (const r of rep.results) lines.push("", ...resultLines(r, r.label ? `Configuration ${r.label}` : "Result"));
  return `${lines.join("\n")}\n`;
}
